from __future__ import annotations

import logging
import re
from typing import Any

from .cue_retime import (
    _acoustic_end_across_spans,
    _estimate_speech_duration_s,
    _repeated_call_units,
    ensure_readable_cue_timings,
)
from .whisper_windows import (
    _WINDOWED_MAX_SPAN_S,
)

_log = logging.getLogger("transub_engine.asr.speech_spans")

_ANIME_VAD_CHUNK_THRESHOLD_S = 0.5


_ANIME_VAD_MAX_GROUP_S = 5.0


_ANIME_VAD_MIN_ISLAND_S = 0.22


_ANIME_VAD_MERGE_GAP_S = 0.5


_ANIME_FRAME_CHAR_CHUNK = 10


def _anime_ten_beam_size(beam_size: int | None) -> int:
    """Anime TEN islands always use greedy decode (WhisperJAV / litagin)."""
    _ = beam_size  # request beam ignored — short islands do not benefit
    return 1


def _resolve_island_vad_backend(timing_align_model: str | None) -> str | None:
    """Pick short-frame island VAD: ``ten`` | ``firered`` | ``None`` (skip).

    ``None`` / ``auto`` / ``vad`` → TEN (default).
    ``firered`` / ``firered-vad`` → FireRedVAD.
    Explicit ``""`` / ``off`` / ``rate`` → no island ASR (windowed/CPS).
    Other ids (whisper-ja, wav2vec2, …) → dual-align path, not island ASR.
    """
    if timing_align_model is None:
        return "ten"
    raw = str(timing_align_model).strip().lower().replace("_", "-")
    if raw in ("auto", "vad"):
        return "ten"
    if raw in ("ten", "ten-vad"):
        return "ten"
    if raw in ("firered", "firered-vad", "fire-red", "fireredvad"):
        return "firered"
    if not raw or raw in ("off", "false", "0", "no", "none", "rate", "cps"):
        return None
    return None


def _anime_uses_ten_island_asr(timing_align_model: str | None) -> bool:
    """True when anime path should run VAD-owned short-frame island ASR."""
    return _resolve_island_vad_backend(timing_align_model) is not None


def _asr_uses_island_vad_path(
    asr_model: str | None,
    timing_align_model: str | None,
) -> bool:
    """Island VAD ASR for anime-whisper (TEN/FireRed) and soft-AV Whisper (FireRed).

    Whisper JA on Silero ``vad_filter`` drops almost all soft-AV mid-film
    (DLDSS-559 m20–m60: ~59s of 60s removed). FireRed islands keep recall.

    ``whisper-large-v2`` (and v3/turbo) with ``timingAlignModel=firered`` must
    take the same island path — otherwise the desktop JA preset only runs
    built-in Silero + CT2 segment stamps and soft-AV timelines drift badly.
    """
    backend = _resolve_island_vad_backend(timing_align_model)
    if backend is None:
        return False
    from ..models_catalog import asr_is_anime_whisper

    if asr_is_anime_whisper(asr_model):
        return True
    mid = str(asr_model or "").strip().lower()
    if backend != "firered":
        return False
    return mid in (
        "whisper-ja-1.5b",
        "whisper-ja",
        "whisper-large-v2",
        "whisper-large-v3",
        "whisper-large-v3-turbo",
    )


def _split_island_spans(
    start: float,
    end: float,
    *,
    max_span_s: float = _WINDOWED_MAX_SPAN_S,
) -> list[tuple[float, float]]:
    """Split oversized VAD islands (CT2-safe ≤180s, or anime short frames ≤5s)."""
    s = float(start)
    e = float(end)
    if e <= s:
        return []
    max_s = max(1.0, float(max_span_s or _WINDOWED_MAX_SPAN_S))
    if e - s <= max_s + 1e-6:
        return [(s, e)]
    out: list[tuple[float, float]] = []
    cursor = s
    while cursor < e - 1e-6:
        nxt = min(e, cursor + max_s)
        out.append((cursor, nxt))
        cursor = nxt
    return out


def group_vad_intervals(
    intervals: list[tuple[float, float]] | None,
    *,
    chunk_threshold_s: float = _ANIME_VAD_CHUNK_THRESHOLD_S,
    max_group_duration_s: float = _ANIME_VAD_MAX_GROUP_S,
) -> list[tuple[float, float]]:
    """
    VAD grouping: merge nearby speech, cap group length.

    Then hard-split any remaining oversize span so each anime ASR call stays
    inside ``max_group_duration_s`` (default 5s).
    """
    ordered = sorted(
        (
            (float(s), float(e))
            for s, e in (intervals or [])
            if float(e) > float(s)
        ),
        key=lambda p: p[0],
    )
    if not ordered:
        return []
    gap = max(0.0, float(chunk_threshold_s))
    max_g = max(1.0, float(max_group_duration_s))
    merged: list[list[float]] = [[ordered[0][0], ordered[0][1]]]
    for s, e in ordered[1:]:
        prev_s, prev_e = merged[-1]
        silence = s - prev_e
        would_exceed = (e - prev_s) > max_g
        if silence > gap or would_exceed:
            merged.append([s, e])
        else:
            merged[-1][1] = max(prev_e, e)
    out: list[tuple[float, float]] = []
    for s, e in merged:
        out.extend(_split_island_spans(s, e, max_span_s=max_g))
    return out


_JA_TURN_ENDER_RE = re.compile(
    r"(?:んですけど|んだけど|ですけど|ますけど|ませんか|ますか|ですか|"
    r"ましょうか|ましょう|ました|でした|ません|ましたっけ|"
    r"ますよ|ですよ|んですよ|です|ます|けど|けれど|から|ので|"
    r"よね|じゃん|かな|だよ|だね|なの|っすよ|っすか|よか|だろ)"
)


_JA_TURN_STARTER_RE = re.compile(
    r"(?:"
    r"あー+|あぁ+|ああっ*|あっ+|ああ+|"
    r"あ(?=ちょっと|でも|の|れ|ー|わかり|本当|ほんと|そう)|"
    r"いや[ぁあ]?|いえ|いやいや|"
    r"ねえ|ねぇ|ねー|"
    r"でも(?=[ぁ-んァ-ン一-龥])|そんな|"
    r"ふふ+|ふーん|はぁ+|ええ+(?![え])|"
    r"んふふ+|うふふ+|あはは+|えへへ+|あは+|"
    r"もう(?=[ぁ-ん])|だめ|ダメ|お願い|"
    r"はい|うん+|んー+|"
    r"なんで|だって|"
    # そう今度 / そうそう / そうよ — not そういう・そう思・それに(via それ not listed)
    r"そう(?!いう|思|なれ|やって)|"
    # じゃあ only — bare じゃ would false-cut じゃん repetition (いいじゃんいいじゃん)
    r"じゃあ|"
    r"わかりました|わかった|わかります|"
    r"本当に|ほんと|ホント|"
    r"よかった|"
    r"あいつ|あれ(?!ば)|"
    r"おっけー+|オッケー+|"
    # After-ellipsis responses (いいね/いいじゃん only via ellipsis cuts — avoid いいじゃん叠词误切)
    # やっ、びっ… but not やっぱ
    r"大丈夫|よし|やっ(?![ぱパ])|わ[ぁあ]|うわぁ|うわ|"
    r"なに|何|だれ|誰|"
    # お島さん / おっさん after clause ender (お願い already matched above)
    r"お(?=[っッ]?[一-龥ぁ-んァ-ン])"
    r")"
)


_JA_TURN_CONTINUATION_PREFIXES = (
    "それに",
    "それで",
    "それは",
    "それを",
    "それから",
    "それでも",
)


_JA_MOAN_OR_BREATH_RE = re.compile(
    r"^[んあぁはふぅっンアッッハヒフヘホ…⋯.。、,\sー～~!！?？]+$"
)


_JA_CLAUSE_SUSPEND_RE = re.compile(
    r"(?:して|って|(?<![んっ])て|が|は|を|に)$"
)


_JA_CONNECTIVE_HEAD_RE = re.compile(
    r"^(?:でも|けど|けれど|じゃあ|それで|そして|あと)$"
)


_JA_ELLIPSIS_AFTER_TURN_RE = re.compile(
    r"^(?:"
    r"はい|うん+|そう(?!いう|思|なれ|やって)|だって|なんで|"
    r"いや[ぁあ]?|いえ|ねえ|ねぇ|じゃあ|"
    r"大丈夫|本当|ほんと|ホント|よし|やっ(?![ぱパ])|わ[ぁあ]|うわぁ|"
    r"いいね|いいよ|いいんだ|いいじゃん|"
    r"なに|何|だれ|誰|え[?？]|お願い|ありがとう|すみません|"
    r"探して|見て|聞いて|知って|わか|まだ"
    r")"
)


def _ja_is_moan_or_breath(text: str) -> bool:
    s = str(text or "").strip()
    if not s:
        return True
    # Short responses are real turns, not moans
    if re.match(r"^(?:うん+|はい|ええ+|そう|よし)$", s):
        return False
    return bool(_JA_MOAN_OR_BREATH_RE.match(s)) and len(s) <= 24


def _ja_head_has_turn_ender(head_r: str) -> bool:
    """True when head ends with a clause/turn ender (not merely contains one nearby)."""
    raw = str(head_r or "")
    if not raw:
        return False
    if re.search(r"[。…⋯？?！!]$", raw):
        return True
    # Anchor at end — avoid ですか eating か inside ですから and missing から$
    suffix = raw[-16:] if len(raw) > 16 else raw
    return bool(re.search(_JA_TURN_ENDER_RE.pattern + r"$", suffix))


def _ja_ellipsis_turn_cuts(text: str) -> list[int]:
    """Cut after … / ⋯ when the following side looks like another speaker turn."""
    raw = str(text or "")
    if not raw or ("…" not in raw and "⋯" not in raw):
        return []
    cuts: list[int] = []
    for m in re.finditer(r"[…⋯]+", raw):
        start = m.end()
        while start < len(raw) and raw[start] in " \t":
            start += 1
        if start >= len(raw) or start < 3:
            continue
        head_r = raw[: m.start()].rstrip()
        tail = raw[start:]
        tail_s = tail.strip()
        if len(head_r) < 2 or len(tail_s) < 2:
            continue
        if _ja_is_moan_or_breath(head_r) or _ja_is_moan_or_breath(tail_s):
            continue
        # Hesitation filler then same-speaker continue: あ…ちょっと / あの…状況
        if re.match(r"^(?:あ+|う+|ん+|あの|その|えっ|えっと)$", head_r):
            continue
        # Short surprise interjection … long reply: おお…魅力に…
        if re.match(r"^(?:おお+|わぁ+|へえ+|ええ+)$", head_r) and len(tail_s) >= 5:
            if not _ja_is_moan_or_breath(tail_s):
                cuts.append(start)
                continue
        # でも…静かに — same speaker connective + thought
        if _JA_CONNECTIVE_HEAD_RE.match(head_r):
            continue
        # Clause suspension then completion: しかして…ヌードですか?
        if _JA_CLAUSE_SUSPEND_RE.search(head_r):
            if not _JA_ELLIPSIS_AFTER_TURN_RE.match(tail_s):
                continue
        elif not _JA_ELLIPSIS_AFTER_TURN_RE.match(tail_s):
            # Topic / soft ender … substantial reply (素人感…探してみます / なんで…まだ)
            soft_end = bool(
                re.search(
                    r"(?:けど|けれど|じゃん|だよ|だね|よね|し|よ|ね|な|感|い|で|ー)$",
                    head_r,
                )
            )
            topic_like = (
                len(head_r) <= 10
                and len(head_r) >= 3
                and bool(re.search(r"[一-龥ぁ-んァ-ン]{2,}$", head_r))
                and not _JA_CONNECTIVE_HEAD_RE.match(head_r)
            )
            reply_like = len(tail_s) >= 4 and bool(
                re.search(r"(?:ます|です|ですか|ますか|だよ|だね|[?？])", tail_s)
                or re.match(r"[一-龥ァ-ン]", tail_s)
            )
            if not ((soft_end or topic_like) and reply_like):
                continue
            # Same-breath continuations after …
            if re.match(r"^(?:その|これ|それ|もっと|こう|そうして)", tail_s):
                continue
        if len(head_r) < 2 or len(tail_s) < 2:
            continue
        cuts.append(start)
    return cuts


def _split_ja_dialogue_turns(text: str) -> list[str]:
    """Split glued JA dialogue turns (two speakers in one ASR island)."""
    raw = str(text or "").strip()
    if not raw or len(raw) < 8:
        return [raw] if raw else []
    cuts: list[int] = []
    for m in _JA_TURN_STARTER_RE.finditer(raw):
        start = m.start()
        if start < 3:
            continue
        head = raw[:start]
        head_r = head.rstrip()
        starter = m.group(0)
        tail = raw[start:]
        if any(tail.startswith(p) for p in _JA_TURN_CONTINUATION_PREFIXES):
            continue
        ok = _ja_head_has_turn_ender(head_r)
        # Soft particles / verb ends before interjections: しよっかあー / いけたああ / じゃんうふふ
        # (Do not apply to でも/そんな/そう/はい — those need a real clause ender.)
        if (
            not ok
            and starter.startswith((
                "あー", "あぁ", "あっ", "ああ", "いや", "いえ",
                "ふふ", "ふーん", "はぁ", "ええ",
                "んふふ", "うふふ", "あはは", "えへへ", "あは",
                "やっ", "わぁ", "うわ", "うわぁ",
            ))
        ):
            if re.search(r"(?:た|だ|る|て|で|か|よ|ね|ん|し|っ)$", head_r):
                ok = True
        if not ok:
            continue
        tail_len = len(tail.strip())
        # はい/うん alone can be a full response turn; other starters need a bit more.
        min_tail = 2 if starter in ("はい", "うん") or starter.startswith(("うん", "んー")) else 3
        if len(head_r) < 3 or tail_len < min_tail:
            continue
        # Avoid orphan turn stubs like lone 「そんな」/ short 「そう」
        if tail_len < 5 and starter in ("でも", "そんな", "ねえ", "ねぇ", "じゃあ"):
            continue
        if tail_len < 4 and starter.startswith("そう"):
            continue
        cuts.append(start)
    cuts.extend(_ja_ellipsis_turn_cuts(raw))
    cuts = sorted(set(cuts))
    if not cuts:
        return [raw]
    parts: list[str] = []
    last = 0
    for cut in cuts:
        if cut <= last:
            continue
        chunk = raw[last:cut].strip()
        if chunk:
            parts.append(chunk)
        last = cut
    tail = raw[last:].strip()
    if tail:
        parts.append(tail)
    return parts if len(parts) > 1 else [raw]


def _split_frame_text_chunks(text: str, *, max_chars: int = _ANIME_FRAME_CHAR_CHUNK) -> list[str]:
    """Split hierarchy: dialogue turns → sentences → commas → ~10-char chunks."""
    raw = str(text or "").strip()
    if not raw:
        return []
    turn_parts = _split_ja_dialogue_turns(raw)
    if len(turn_parts) > 1:
        out: list[str] = []
        for part in turn_parts:
            out.extend(_split_frame_text_chunks(part, max_chars=max_chars))
        return [c for c in out if c and c.strip()]
    chunks = [p for p in re.split(r"(?<=[。？?！!])", raw) if p and p.strip()]
    if not chunks:
        chunks = [raw]
    if len(chunks) == 1 and len(raw) > 12:
        # Ellipsis often marks a soft turn without 。
        ellip = [p for p in re.split(r"(?<=[…⋯])", raw) if p and p.strip()]
        if len(ellip) > 1 and all(len(p.strip()) >= 2 for p in ellip):
            lexical = 0
            for p in ellip:
                core = re.sub(r"[…⋯]+$", "", p.strip())
                if core and not _ja_is_moan_or_breath(core):
                    lexical += 1
            if lexical >= 2:
                chunks = ellip
    if len(chunks) == 1 and len(raw) > 15:
        comma = [p for p in re.split(r"(?<=[、，,])", raw) if p and p.strip()]
        if len(comma) > 1:
            connective = any(
                re.search(r"[がでて]、?$", p.strip()) and len(p.strip()) <= 12
                for p in comma[:-1]
            )
            if not connective:
                chunks = comma
    # Never CJK-bisect: させてい|ただいて / 変わって大|変だ shred one polite turn.
    return [c.strip() for c in chunks if c and c.strip()]


def split_frame_text_to_cues(
    text: str,
    start: float,
    end: float,
    *,
    max_chars: int = _ANIME_FRAME_CHAR_CHUNK,
) -> list[dict[str, Any]]:
    """
    Paint island text onto ``[start, end]`` with char-proportional sub-cues.

    Timing comes from the VAD frame; intra-frame splits are synthetic
    (char-proportional, not acoustic). Prefer ``paint_text_onto_speech_spans``
    when PCM speech subspans are available.
    """
    chunks = _split_frame_text_chunks(text, max_chars=max_chars)
    if not chunks:
        return []
    s = float(start)
    e = float(end)
    if e <= s:
        e = s + 0.35
    if len(chunks) == 1:
        return [{"start": s, "end": e, "text": chunks[0]}]
    total_chars = sum(len(c) for c in chunks) or 1
    duration = e - s
    out: list[dict[str, Any]] = []
    cursor = s
    for i, chunk in enumerate(chunks):
        if i == len(chunks) - 1:
            chunk_end = e
        else:
            chunk_end = cursor + duration * (len(chunk) / total_chars)
        out.append(
            {
                "start": cursor,
                "end": max(cursor + 0.05, chunk_end),
                "text": chunk,
            }
        )
        cursor = chunk_end
    return out


def nudge_cue_starts_past_silence(
    cues: list[dict[str, Any]] | None,
    pcm: Any,
    *,
    sample_rate: int = 16000,
    rms_floor: float = 0.0022,
    win_s: float = 0.12,
    hop_s: float = 0.02,
    min_keep_s: float = 0.28,
    max_nudge_s: float = 1.35,
) -> list[dict[str, Any]]:
    """
    Snap cue starts forward past leading VAD/pad silence on soft-AV mix.

    FireRed islands often include 0.5–1s of near-silent pad before the first
    audible syllable (HODV-22113 「一年ぶりなんだし」 @ 13.5s). Without this,
    SILENT_START gates fire even when the text itself is correct.
    """
    if not cues:
        return []
    try:
        import numpy as np
    except Exception:
        return [dict(c) for c in cues if isinstance(c, dict)]
    if pcm is None:
        return [dict(c) for c in cues if isinstance(c, dict)]
    try:
        arr = np.asarray(pcm, dtype=np.float32).reshape(-1)
    except Exception:
        return [dict(c) for c in cues if isinstance(c, dict)]
    sr = max(1000, int(sample_rate or 16000))
    win = max(1, int(sr * float(win_s)))
    hop = max(1, int(sr * float(hop_s)))
    out: list[dict[str, Any]] = []
    for cue in cues:
        if not isinstance(cue, dict):
            continue
        item = dict(cue)
        start = float(item.get("start") or 0)
        end = float(item.get("end") or start)
        dur = end - start
        if dur < 0.45:
            out.append(item)
            continue
        i0 = max(0, int(start * sr))
        i1 = min(arr.size, int(end * sr))
        if i1 - i0 < win:
            out.append(item)
            continue
        # Only nudge when the lead-in is actually quiet.
        lead = arr[i0 : min(arr.size, i0 + win)]
        if lead.size == 0:
            out.append(item)
            continue
        lead_rms = float(np.sqrt(np.mean(np.square(lead))) + 1e-12)
        if lead_rms >= float(rms_floor) * 0.85:
            out.append(item)
            continue
        limit = min(i1 - win, i0 + int(float(max_nudge_s) * sr))
        found = None
        t = i0
        while t <= limit:
            chunk = arr[t : t + win]
            if chunk.size < win // 2:
                break
            rms = float(np.sqrt(np.mean(np.square(chunk))) + 1e-12)
            if rms >= float(rms_floor):
                found = t / float(sr)
                break
            t += hop
        if found is not None and found > start + 0.08:
            new_start = min(found, end - float(min_keep_s))
            if new_start > start + 0.05:
                item["start"] = round(new_start, 3)
        out.append(item)
    return out


def pcm_speech_intervals(
    pcm: Any,
    sample_rate: int,
    *,
    offset_s: float = 0.0,
    # Transub Pro parity (timing_pcm_spans / energy_envelope_np hop_ms=10).
    frame_ms: float = 10.0,
    min_speech_s: float = 0.12,
    merge_gap_s: float = 0.22,
    pad_s: float = 0.04,
    end_pad_s: float | None = None,
) -> list[tuple[float, float]]:
    """
    Find speech-active subspans inside a mono float32 clip via frame RMS.

    Used to keep island cue paint off leading/trailing VAD pad and mid-island
    silence — char-proportional paint on the full VAD frame is the main source
    of large early/late drift on soft-AV TEN paths.

    Onset uses a firmer gate (sharp cue starts); offset uses a lower gate with
    hangover so soft phrase tails (「おいしい」「よかった」) are not clipped
    early — a common soft-AV timestamp regression.

    Defaults match Transub Pro ``timing_pcm_spans``: 10 ms RMS hop, soft offset
    (~2.2% peak) and ~160 ms hang so quiet JA tails stay inside the span.
    """
    try:
        import numpy as np
    except Exception:
        return []
    if pcm is None:
        return []
    try:
        arr = np.asarray(pcm, dtype=np.float32).reshape(-1)
    except Exception:
        return []
    sr = max(1000, int(sample_rate or 16000))
    if arr.size < int(0.08 * sr):
        return []
    hop = max(1, int(sr * max(0.01, float(frame_ms)) / 1000.0))
    n_frames = int(arr.size // hop)
    if n_frames < 2:
        return []
    # Vectorized frame RMS (avoid Python loop on long islands).
    usable = n_frames * hop
    frames = arr[:usable].reshape(n_frames, hop)
    rms = np.sqrt(np.mean(np.square(frames), axis=1) + 1e-12)
    peak = float(np.max(rms)) if rms.size else 0.0
    if peak < 1e-6:
        return []
    p20 = float(np.percentile(rms, 20))
    # Hysteresis: start firm, end soft (Pro timing_pcm_spans parity).
    onset_thr = max(peak * 0.07, p20 * 1.9, 1e-4)
    offset_thr = max(peak * 0.022, p20 * 0.95, 1e-5)
    offset_thr = min(offset_thr, onset_thr * 0.75)
    # ~160ms hangover below offset before we actually close the span.
    hang_frames = max(2, int(round(0.16 * sr / hop)))

    raw: list[list[float]] = []
    cur: list[float] | None = None
    quiet_run = 0
    for i, level in enumerate(rms.tolist()):
        t0 = float(offset_s) + (i * hop) / float(sr)
        t1 = float(offset_s) + ((i + 1) * hop) / float(sr)
        if cur is None:
            if level >= onset_thr:
                cur = [t0, t1]
                quiet_run = 0
        else:
            if level >= offset_thr:
                cur[1] = t1
                quiet_run = 0
            else:
                # Hangover: wait before closing, but do NOT advance end into
                # silence (that shrinks the pause and merge_gap glues turns).
                quiet_run += 1
                if quiet_run >= hang_frames:
                    raw.append(cur)
                    cur = None
                    quiet_run = 0
    if cur is not None:
        raw.append(cur)

    filtered = [[s, e] for s, e in raw if (e - s) >= float(min_speech_s)]
    if not filtered:
        # Soft murmur: keep the loudest contiguous run even if short.
        if raw:
            best = max(raw, key=lambda p: p[1] - p[0])
            if (best[1] - best[0]) >= 0.06:
                filtered = [best]
            else:
                return []
        else:
            return []

    merged: list[list[float]] = []
    gap = float(merge_gap_s)
    for s, e in filtered:
        if merged and s <= merged[-1][1] + gap:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])

    clip_end = float(offset_s) + (arr.size / float(sr))
    pad_start = max(0.0, float(pad_s))
    pad_end = max(pad_start, float(end_pad_s) if end_pad_s is not None else pad_start + 0.06)
    out: list[tuple[float, float]] = []
    for s, e in merged:
        s2 = max(float(offset_s), s - pad_start)
        e2 = min(clip_end, e + pad_end)
        if e2 - s2 >= 0.06:
            out.append((s2, e2))
    return out


def _split_island_at_mix_silences(
    pcm: Any,
    sample_rate: int,
    start_s: float,
    end_s: float,
    *,
    min_silence_s: float = 0.48,
    max_piece_s: float = 6.0,
    frame_ms: float = 30.0,
) -> list[tuple[float, float]]:
    """
    Cut a Demucs/TEN island at clear mix silences without dropping *speech*.

    Soft dialogue often sits below a speech-gate on the mix even when Demucs
    vocals VAD kept it — so we must not replace the island with mix-speech
    spans. Instead, trim out only clear pauses so ASR frames start/end on
    speech (abutting mid-silence cuts were re-merged by group_vad and left
    long silent pads that drifted cue paint).

    Require ~0.48s of true quiet (no 0.9× fudge): 0.30–0.36s mid-phrase dips
    (e.g. breath inside 「昨日テレビで」) must NOT become ASR frame boundaries.
    """
    try:
        import numpy as np
    except Exception:
        return [(float(start_s), float(end_s))]
    s0 = float(start_s)
    e0 = float(end_s)
    if e0 <= s0 + 0.05:
        return []
    try:
        arr = np.asarray(pcm, dtype=np.float32).reshape(-1)
    except Exception:
        return [(s0, e0)]
    sr = max(1000, int(sample_rate or 16000))
    i0 = max(0, int(round(s0 * sr)))
    i1 = min(arr.size, int(round(e0 * sr)))
    if i1 <= i0 + int(0.15 * sr):
        return [(s0, e0)]
    hop = max(1, int(sr * max(0.01, float(frame_ms)) / 1000.0))
    n_frames = int((i1 - i0) // hop)
    if n_frames < 4:
        return [(s0, e0)]
    usable = n_frames * hop
    frames = arr[i0 : i0 + usable].reshape(n_frames, hop)
    rms = np.sqrt(np.mean(np.square(frames), axis=1) + 1e-12)
    peak = float(np.max(rms)) if rms.size else 0.0
    if peak < 1e-6:
        return [(s0, e0)]
    # Silence gate: only near-floor frames count. Soft speech must stay "active".
    # Slightly stricter than the old peak*0.025 so brief mid-phrase dips fail.
    p15 = float(np.percentile(rms, 15))
    p50 = float(np.percentile(rms, 50))
    silence_thr = max(peak * 0.03, p15 * 1.5, min(p50 * 0.45, peak * 0.07), 1e-5)
    quiet = rms < silence_thr
    min_sil = max(0.35, float(min_silence_s))
    min_sil_frames = max(2, int(round(min_sil * sr / hop)))
    # Quiet runs as absolute [sil_start, sil_end) — trim these out of pieces.
    silences: list[tuple[float, float]] = []
    i = 0
    while i < n_frames:
        if not bool(quiet[i]):
            i += 1
            continue
        j = i
        while j < n_frames and bool(quiet[j]):
            j += 1
        if (j - i) >= min_sil_frames:
            sil_a = s0 + (i * hop) / float(sr)
            sil_b = s0 + (j * hop) / float(sr)
            # Full duration required — do not accept 0.9× near-miss micro-pauses.
            if sil_b - sil_a >= min_sil:
                silences.append((float(sil_a), float(sil_b)))
        i = j

    pieces: list[tuple[float, float]] = []
    cursor = s0
    for sil_a, sil_b in silences:
        # Keep a tiny pad into the pause so phrase tails are not clipped.
        pad = min(0.08, max(0.03, (sil_b - sil_a) * 0.12))
        piece_end = min(sil_a + pad, sil_b - 0.05)
        if piece_end > cursor + 0.18:
            pieces.append((cursor, float(piece_end)))
        nxt = max(piece_end + 0.12, sil_b - pad)
        if nxt < e0 - 0.12:
            cursor = float(nxt)
        else:
            cursor = e0
            break
    if cursor < e0 - 0.08:
        pieces.append((cursor, e0))
    if not pieces:
        pieces = [(s0, e0)]

    # Hard-cap leftover mega-pieces. Prefer a *true* quiet frame; never pick a
    # mid-phrase micro-dip (that bisected 「昨日テレビで」 at ~5.3s). If no quiet
    # cut exists, fall back to even chops so group_vad does not inherit 20s blobs.
    cap = max(5.0, float(max_piece_s))
    final: list[tuple[float, float]] = []
    for a, b in pieces:
        if b - a <= cap + 0.05:
            final.append((a, b))
            continue
        stack = [(a, b)]
        while stack:
            u, v = stack.pop()
            if v - u <= cap + 0.05:
                final.append((u, v))
                continue
            ui = max(0, int(round((u - s0) * sr / hop)))
            vi = min(n_frames, int(round((v - s0) * sr / hop)))
            if vi - ui < 6:
                final.append((u, v))
                continue
            lo = ui + max(2, (vi - ui) // 3)
            hi = vi - max(2, (vi - ui) // 3)
            if hi <= lo:
                mid_i = (ui + vi) // 2
            else:
                mid_i = int(lo + int(np.argmin(rms[lo:hi])))
            # Only treat as a pause cut when the valley is actually quiet.
            if float(rms[mid_i]) > max(silence_thr * 1.25, peak * 0.06):
                mid_t = u + (v - u) * 0.5
            else:
                mid_t = s0 + (mid_i * hop) / float(sr)
            mid_t = min(max(mid_t, u + 0.45), v - 0.45)
            # 80ms gap so group_vad does not immediately glue the halves.
            stack.append((mid_t + 0.04, v))
            stack.append((u, mid_t - 0.04))
    final.sort(key=lambda p: p[0])
    return [(float(a), float(b)) for a, b in final if b > a + 0.08]


def refine_demucs_vad_intervals(
    intervals: list[tuple[float, float]] | None,
    pcm: Any,
    sample_rate: int,
    *,
    long_island_s: float = 10.0,
    min_silence_s: float = 0.48,
    max_piece_s: float = 6.0,
) -> list[tuple[float, float]]:
    """
    Re-split Demucs-driven VAD mega-islands at mix *silences* (coverage-preserving).

    Demucs vocals often keep TEN hot across soft-AV stretches (breath / residual),
    yielding 20–40s mega-islands. Hard 5s chops then bisect turns.

    Only islands longer than ~8s are silence-split (full-film runs with
    long_island≈2.8 over-fragmented 1105→2318 and scrambled cue paint). Keep
    ≥0.48s clear pauses and a quiet-aware hard-cap so mid-phrase micro-dips
    (e.g. inside 「昨日テレビで」) do not become frame boundaries. Soft lines
    that fail a mix speech-gate are still kept.
    """
    raw = [
        (float(s), float(e))
        for s, e in (intervals or [])
        if float(e) > float(s) + 0.05
    ]
    if not raw:
        return []
    if pcm is None:
        return raw
    try:
        import numpy as np

        arr = np.asarray(pcm, dtype=np.float32).reshape(-1)
    except Exception:
        return raw
    sr = max(1000, int(sample_rate or 16000))
    if arr.size < int(0.2 * sr):
        return raw

    # Mega-islands only — medium dialogue turns stay intact for Qwen paint.
    lim = max(5.0, float(long_island_s))
    out: list[tuple[float, float]] = []
    refined_n = 0
    for s0, e0 in raw:
        dur = e0 - s0
        if dur <= lim:
            out.append((s0, e0))
            continue
        parts = _split_island_at_mix_silences(
            arr,
            sr,
            s0,
            e0,
            min_silence_s=float(min_silence_s),
            max_piece_s=float(max_piece_s),
        )
        if not parts:
            out.append((s0, e0))
            continue
        # One piece still counts when lead/trail silence was trimmed.
        if len(parts) == 1:
            a, b = parts[0]
            if abs(a - s0) > 0.04 or abs(b - e0) > 0.04:
                refined_n += 1
                out.append((a, b))
            else:
                out.append((s0, e0))
            continue
        refined_n += 1
        out.extend(parts)

    if refined_n:
        _log.info(
            "Demucs-VAD refine: long_islands=%d -> intervals %d→%d (silence-split, keep coverage)",
            refined_n,
            len(raw),
            len(out),
        )
    out.sort(key=lambda p: p[0])
    # Only glue sub-0.55s blips (not the aggressive 1.0s/1.2s merge that
    # re-created fat windows after silence cuts).
    return _coalesce_short_vad_islands(
        out, short_s=0.55, max_gap_s=0.55, max_merged_s=4.5
    )


def _coalesce_short_vad_islands(
    intervals: list[tuple[float, float]],
    *,
    short_s: float = 0.55,
    max_gap_s: float = 0.55,
    max_merged_s: float = 4.5,
) -> list[tuple[float, float]]:
    """
    Merge only tiny leftover blips after silence-split (too short for Qwen alone).

    Keep thresholds tight so we do not undo pause cuts and recreate mega-frames.
    """
    if len(intervals) <= 1:
        return list(intervals or [])
    ordered = sorted(
        ((float(s), float(e)) for s, e in intervals if float(e) > float(s) + 0.05),
        key=lambda p: p[0],
    )
    if not ordered:
        return []
    short = max(0.2, float(short_s))
    gap_lim = max(0.15, float(max_gap_s))
    cap = max(short + 0.5, float(max_merged_s))
    out: list[list[float]] = [[ordered[0][0], ordered[0][1]]]
    for s, e in ordered[1:]:
        prev_s, prev_e = out[-1]
        gap = float(s) - float(prev_e)
        prev_dur = float(prev_e) - float(prev_s)
        dur = float(e) - float(s)
        merged_dur = float(e) - float(prev_s)
        should = (
            gap <= gap_lim
            and merged_dur <= cap
            and (prev_dur < short or dur < short)
        )
        if should:
            out[-1][1] = max(float(prev_e), float(e))
        else:
            out.append([float(s), float(e)])
    return [(a, b) for a, b in out]


def paint_text_onto_speech_spans(
    text: str,
    *,
    island_start: float,
    island_end: float,
    speech_spans: list[tuple[float, float]] | None,
    max_chars: int = _ANIME_FRAME_CHAR_CHUNK,
    preserve_acoustic_ends: bool = False,
) -> list[dict[str, Any]]:
    """
    Paint ASR text onto speech-active subspans (skip mid-island silence).

    Chunks are packed into spans by duration weight so cue starts track
    speech onsets (not mid-gap). Falls back to full-island char-proportional
    paint when no usable spans.

    When ``preserve_acoustic_ends`` is True (Qwen TEN/FireRed path), keep
    measured PCM span ends instead of capping by speaking-rate soft_cap, and
    finish with ``stretch_to_reading_rate=False`` so ensure_readable cannot
    shrink cues shorter than the spoken audio.
    """
    s0 = float(island_start)
    e0 = float(island_end)
    if e0 <= s0:
        e0 = s0 + 0.35
    stretch = not bool(preserve_acoustic_ends)

    def _finish(
        cues: list[dict[str, Any]],
        *,
        media_end_s: float | None = None,
    ) -> list[dict[str, Any]]:
        return ensure_readable_cue_timings(
            cues,
            media_end_s=e0 if media_end_s is None else media_end_s,
            stretch_to_reading_rate=stretch,
        )

    spans = [
        (float(a), float(b))
        for a, b in (speech_spans or [])
        if float(b) > float(a) + 0.05
    ]
    clamped: list[tuple[float, float]] = []
    for a, b in spans:
        cs = max(s0, min(a, e0))
        ce = max(cs + 0.05, min(b, e0))
        if ce > cs + 0.05:
            clamped.append((cs, ce))
    if not clamped:
        return _finish(split_frame_text_to_cues(text, s0, e0, max_chars=max_chars))
    if len(clamped) == 1:
        return _finish(
            split_frame_text_to_cues(
                text, clamped[0][0], clamped[0][1], max_chars=max_chars
            )
        )

    chunks = _split_frame_text_chunks(text, max_chars=max_chars)
    if not chunks:
        return []
    if len(chunks) == 1:
        # One ASR line on a multi-span island.
        #
        # Prior logic pinned the cue to the *first* RMS-fitting span only, which
        # crushed ~3s soft-AV turns into ~0.7–1.2s flashes (DLDSS-553: dialogue
        # continues with no subtitle). Stretch to speaking-rate need across
        # *consecutive* spans, but stop at a large mid-island hole so
        # under-segmented multi-phrase frames (DLDSS-559 「また作るね」) do not
        # ghost across later turns.
        a0 = float(clamped[0][0])
        last_end = float(clamped[-1][1])
        island_avail = max(0.35, float(e0) - a0)
        need = _estimate_speech_duration_s(
            chunks[0], available_s=island_avail
        )
        total_speech = sum(max(0.0, b - a) for a, b in clamped)
        # Name-call loops own N measured peaks (DLDSS-553 「風香×3」 ~3s) —
        # reading-rate need is too short; cover acoustic peaks instead.
        calls = _repeated_call_units(chunks[0])
        if calls is not None:
            grown = _acoustic_end_across_spans(
                clamped,
                anchor_s=a0,
                boundary_s=float(e0),
                max_peaks=int(calls[0]),
            )
            end = float(grown) if grown is not None else min(last_end, a0 + need)
            end = max(end, a0 + 0.28)
            end = min(end, last_end, float(e0))
            return _finish(
                split_frame_text_to_cues(
                    chunks[0], a0, end, max_chars=max_chars
                ),
                media_end_s=e0,
            )
        # Under-segmented: short text vs much longer multi-span speech — pin to
        # the best-fitting span only (do not start on a leading blip and ghost).
        if (
            len(clamped) >= 2
            and need < total_speech * 0.45
        ):
            # Prefer a span that can actually hold speaking-rate need; a leading
            # 0.3s blip that barely clears need*0.5 must not win over the real
            # phrase (DLDSS-559 「また作るね」).
            adequate = [
                (i, sp)
                for i, sp in enumerate(clamped)
                if (sp[1] - sp[0]) >= max(0.28, need * 0.85)
            ]
            if adequate:
                _, sp = adequate[0]
            else:
                _, sp = max(enumerate(clamped), key=lambda it: it[1][1] - it[1][0])
            a = float(sp[0])
            if preserve_acoustic_ends:
                end = min(float(sp[1]), float(e0))
            else:
                end = min(
                    float(sp[1]),
                    a + max(need + 0.25, need * 1.25),
                    float(e0),
                )
            end = max(end, a + min(0.28, max(0.05, float(sp[1]) - a)))
            # Cap media_end at this cue so ensure_readable stretch cannot re-grow
            # into later orphan spans on the same island.
            return _finish(
                split_frame_text_to_cues(
                    chunks[0], a, end, max_chars=max_chars
                ),
                media_end_s=end,
            )
        grown_end = a0
        for sa, sb in clamped:
            if float(sa) > grown_end + 0.55 and grown_end > a0:
                break
            grown_end = max(grown_end, float(sb))
            if grown_end - a0 >= need:
                break
        end = max(grown_end, a0 + need)
        end = min(end, last_end, float(e0), a0 + max(need + 0.45, need * 1.35))
        return _finish(
            split_frame_text_to_cues(
                chunks[0], a0, end, max_chars=max_chars
            ),
            media_end_s=e0,
        )

    # 1:1 — each chunk owns one speech onset; expand into inter-span silence
    # by speaking rate so long JA turns are not trapped in 80–150ms RMS blips.
    if len(chunks) == len(clamped):
        provisional: list[dict[str, Any]] = []
        for i, (chunk, (a, b)) in enumerate(zip(chunks, clamped)):
            if i + 1 < len(clamped):
                boundary = float(clamped[i + 1][0])
            else:
                boundary = float(e0)
            available = max(0.05, boundary - float(a) - 0.02)
            need = _estimate_speech_duration_s(chunk, available_s=available)
            span_dur = max(0.05, float(b) - float(a))
            if preserve_acoustic_ends:
                # Keep measured PCM end; only grow into the gap when the span
                # is shorter than speaking-rate need (flash blip).
                end = min(float(b), float(a) + available)
                if span_dur < need:
                    end = min(
                        max(float(b), float(a) + need),
                        float(a) + available,
                    )
            else:
                # Soft tails: keep measured span end when it is close to
                # speaking-rate need. Multi-phrase RMS islands are often
                # 1.5–2s for a 4-char line (DLDSS-559 cue3) — cap those by
                # need so the next line is not pushed into silence.
                if span_dur <= max(need * 1.3, need + 0.4):
                    end = min(max(float(b), float(a) + need), float(a) + available)
                else:
                    end = min(float(a) + need + 0.1, float(b), float(a) + available)
            end = max(end, float(a) + min(0.28, available))
            provisional.append({"start": float(a), "end": float(end), "text": chunk})
        # If a short line released the tail of a fat RMS span, pull the next cue
        # start forward so it keeps the continuous speech (6.3→7.9 「作ってみた」)
        # instead of waiting for the next RMS blip in silence.
        if not preserve_acoustic_ends:
            for i in range(len(provisional) - 1):
                cur_end = float(provisional[i]["end"])
                nxt = provisional[i + 1]
                gap = float(nxt["start"]) - cur_end
                if 0.2 < gap < 1.25:
                    nxt["start"] = cur_end + 0.05
                    if float(nxt["end"]) < float(nxt["start"]) + 0.3:
                        # Keep original span end when possible.
                        orig_b = (
                            float(clamped[i + 1][1])
                            if i + 1 < len(clamped)
                            else float(nxt["end"])
                        )
                        need_n = _estimate_speech_duration_s(
                            str(nxt.get("text") or ""),
                            available_s=max(0.35, orig_b - float(nxt["start"])),
                        )
                        nxt["end"] = max(
                            float(nxt["start"]) + need_n,
                            min(orig_b, float(nxt["start"]) + max(need_n, 0.45)),
                        )
        return _finish(provisional)

    # More spans than text chunks: map chunks onto the best-matching spans (by
    # duration), drop leftover residual blips — do not weight-paint across orphans.
    if len(chunks) < len(clamped):
        remaining = list(clamped)
        provisional = []
        for chunk in chunks:
            need = _estimate_speech_duration_s(
                chunk,
                available_s=max(0.35, remaining[-1][1] - remaining[0][0]),
            )
            # Earliest span that can hold this line; fallback to longest left.
            fit = [
                (i, sp)
                for i, sp in enumerate(remaining)
                if (sp[1] - sp[0]) >= max(0.22, need * 0.5)
            ]
            if fit:
                idx, sp = fit[0]
            else:
                idx, sp = max(
                    enumerate(remaining),
                    key=lambda it: it[1][1] - it[1][0],
                )
            a = float(sp[0])
            # Grow through following remaining spans until speaking-rate need
            # (same consecutive-span rule as the single-chunk path).
            end = float(sp[1])
            for j in range(idx, len(remaining)):
                sa, sb = remaining[j]
                if float(sa) > end + 0.55 and end > a:
                    break
                end = max(end, float(sb))
                if end - a >= need:
                    break
            end = max(end, a + need)
            if preserve_acoustic_ends:
                end = min(end, float(remaining[-1][1]), float(e0))
            else:
                end = min(
                    end,
                    float(remaining[-1][1]),
                    float(e0),
                    a + max(need + 0.45, need * 1.35),
                )
            provisional.append(
                {"start": a, "end": max(a + 0.28, end), "text": chunk}
            )
            # Consume spans overlapped by this cue so later chunks start later.
            consumed = 0
            for j in range(idx, len(remaining)):
                sa, sb = remaining[j]
                if float(sa) >= end - 0.05:
                    break
                consumed += 1
            del remaining[idx : idx + max(1, consumed)]
            if not remaining:
                break
        provisional.sort(key=lambda c: float(c["start"]))
        return _finish(provisional)

    weights = [max(1, len(c)) for c in chunks]
    total_w = float(sum(weights)) or 1.0
    speech_durs = [b - a for a, b in clamped]
    total_speech = float(sum(speech_durs))
    if total_speech <= 0.05:
        return split_frame_text_to_cues(text, s0, e0, max_chars=max_chars)
    budgets = [max(1.0, total_w * (d / total_speech)) for d in speech_durs]

    groups: list[list[str]] = [[] for _ in clamped]
    span_i = 0
    used_w = 0.0
    for i, (chunk, w) in enumerate(zip(chunks, weights)):
        groups[span_i].append(chunk)
        used_w += float(w)
        last_chunk = i + 1 >= len(chunks)
        last_span = span_i + 1 >= len(clamped)
        if not last_chunk and not last_span and used_w >= budgets[span_i] - 1e-6:
            span_i += 1
            used_w = 0.0

    out: list[dict[str, Any]] = []
    for (a, b), group in zip(clamped, groups):
        if not group:
            continue
        joined = "".join(group)
        out.extend(split_frame_text_to_cues(joined, a, b, max_chars=max_chars))
    if not out:
        return split_frame_text_to_cues(text, s0, e0, max_chars=max_chars)
    return _finish(out)

def _clamp_cues_to_span(
    cues: list[dict[str, Any]],
    start: float,
    end: float,
) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for cue in cues or []:
        item = dict(cue)
        cs = max(float(start), min(float(item.get("start") or start), float(end)))
        ce = max(cs + 0.05, min(float(item.get("end") or cs), float(end)))
        item["start"] = cs
        item["end"] = ce
        out.append(item)
    return out
